    private int msh(int nums[], int low, int high){
        int cnt =0;
        if(low>=high){
            return 0;
        }
        int mid = low + (high- low)/ 2;
        cnt+=msh(nums, low, mid);
        cnt+=msh(nums, mid + 1, high);
        cnt+=merge(nums, low, mid, high);
        return cnt;
    }
