class Solution {
   public:
    long long int numberOfInversions(vector<int> nums) {
        long long int inversion = 0;
        ms(nums, 0, nums.size()-1, inversion);
        return inversion;
    }
    // ms stands for merge sort
    // as u can see below inversion count is passed as a refernce
    void ms(vector<int>& nums, int low, int high, long long int& inversion){
        if(low >= high) return;
        int mid = low + (high-low)/2;
        ms(nums,low,mid,inversion);
        ms(nums,mid+1,high,inversion);
        merge(nums,low,mid,high,inversion);
    }
    void merge(vector<int>& nums, int low, int mid, int high, long long int& inversion){
        vector<int> temp;
        int left = low, right = mid + 1;
        while(left <= mid && right <= high){
            if(nums[left] <= nums[right]) temp.push_back(nums[left++]);
            else {
// [1,2,3,5,6][2,1,3]
//      l   m  r
// nums[l] > nums[r]
// but instead of inversion++, inversion is (m-l+1)
// reason: nums[r] is also lesser than 3,5,6 
// therefore, just find lenth from l to m index
                inversion += mid - left + 1;
                temp.push_back(nums[right++]);
            }
        }
        while(left <= mid) temp.push_back(nums[left++]);
        while(right <= high) temp.push_back(nums[right++]);
        for(int i = 0; i < temp.size(); i++)
            nums[low + i] = temp[i];
    }
};
