## Intuition
An inversion is a pair of indices `(i, j)` such that:

- `i < j`
- `nums[i] > nums[j]`

A brute-force approach checks every pair, resulting in **O(n²)** time complexity.

We can optimize this using **Merge Sort**. While merging two sorted halves, whenever an element from the right half is placed before an element from the left half, it forms inversions with all the remaining elements in the left half.

---

## Algorithm

1. Divide the array into two halves recursively using Merge Sort.
2. Count inversions in the left half.
3. Count inversions in the right half.
4. While merging:
   - If `nums[i] <= nums[j]`, place `nums[i]` into the temporary array.
   - Otherwise:
     - Place `nums[j]` into the temporary array.
     - Since both halves are sorted, all remaining elements from `i` to `mid` are greater than `nums[j]`.
     - Add `(mid - i + 1)` to the inversion count.
5. Copy the merged array back into the original array.
6. Return the total inversion count.

---

## Solution
```cpp[]
class Solution {
    long long counter = 0;

private:
    void merge(vector<int>& nums, int start, int mid, int end) {
        int i = start;
        int j = mid + 1;

        vector<int> temp;

        while (i <= mid && j <= end) {
            // Use <= to avoid counting equal elements as inversions
            if (nums[i] <= nums[j]) {
                temp.push_back(nums[i]);
                i++;
            } else {
                temp.push_back(nums[j]);
                counter += (mid - i + 1);
                j++;
            }
        }

        while (i <= mid) {
            temp.push_back(nums[i]);
            i++;
        }

        while (j <= end) {
            temp.push_back(nums[j]);
            j++;
        }

        // Copy back to original array
        for (int k = 0; k < temp.size(); k++) {
            nums[start + k] = temp[k];
        }
    }

    void mergeSort(vector<int>& nums, int start, int end) {
        if (start >= end)
            return;

        int mid = start + (end - start) / 2;

        mergeSort(nums, start, mid);
        mergeSort(nums, mid + 1, end);

        merge(nums, start, mid, end);
    }

public:
    long long int numberOfInversions(vector<int> nums) {
        counter = 0;

        if (nums.empty())
            return 0;

        mergeSort(nums, 0, nums.size() - 1);
        return counter;
    }
};
```
